<script setup lang="ts">
import { onLaunch,onShow,onHide } from '@dcloudio/uni-app'
import { useSession } from './stores/session'
import { startNotifications,stopNotifications } from './liveNotifications'
import { readSessionValue,expireSession } from './sessionStorage'
onLaunch(()=>{useSession().restore()})
onShow(()=>{const token=readSessionValue('token');startNotifications(token,()=>expireSession(token))})
onHide(()=>stopNotifications())
</script>
